from typing import Any, Callable, Mapping, Tuple, Union
from functools import wraps, partial, contextmanager
import time

def ttl_cache(maxsize: int = 128, ttl: int = 600, timer: Callable[[Any], float] = time.monotonic, typed: bool = False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    Args:
    - maxsize (int): The maximum number of items in the caching dictionary.
    - ttl (int): The time-to-live for each item in seconds.
    - timer (Callable[[Any], float]): A function to return the current time.
    - typed (bool): Whether to cache based on the type of the arguments.

    Returns:
    - callable: A callable that wraps `fn` with memoization.
    """
    def memoized(fn: Callable[[Tuple[Any, ...], Mapping[str, Any]], Any]) -> Callable[[Tuple[Any, ...], Mapping[str, Any]], Any]:
        memoized_results: Mapping[Tuple[Any, ...], Any] = {}
        last_accessed: Mapping[Tuple[Any, ...], float] = {}

        @wraps(fn)
        def _memoized(*args, **kwargs):
            key = (fn, args, frozenset(kwargs.items() if typed else kwargs.values()))
            if key in memoized_results:
                last_accessed[key] = timer()
                if timer() - last_accessed[key] > ttl:
                    del memoized_results[key]
            if key not in memoized_results:
                memoized_results[key] = fn(*args, **kwargs)
            return memoized_results[key]

        @contextmanager
        def put(*args, **kwargs):
            key = (fn, args, frozenset(kwargs.items() if typed else kwargs.values()))
            yield functools.partial(memoized_results.__setitem__, key)

        def forget(*args, **kwargs):
            key = (fn, args, frozenset(kwargs.items() if typed else kwargs.values()))
            if key in memoized_results:
                del memoized_results[key]

        def clear():
            memoized_results.clear()
            last_accessed.clear()

        _memoized.put = put
        _memoized.forget = forget
        _memoized.clear = clear
        return _memoized

    return memoized
