def namesAndDescriptions(self, all=False) -> Iterable[Dict[str, str]]:
    """
    Return attribute names and descriptions defined by interface.

    Parameters:
        all (bool): If True, return all attributes including those inherited from parent classes.

    Returns:
        Iterable[Dict[str, str]]: A callable object that maps attribute names to their descriptions.
    """
