    @functools.lru_cache(maxsize=None)
    def _generate_dict():
        class_dict = {}
        for name in dir(self.__class__):
            if not name.startswith('__'):
                value = getattr(self.__class__, name)
                if isinstance(value, property):
                    docstring = value.__doc__ or ''
                    class_dict[name] = docstring
                elif callable(value) or inspect.isroutine(value) or inspect.isfunction(value):
                    if '__doc__' in value.__dict__:
                        docstring = value.__dict__['__doc__'] or ''
                        class_dict[name] = docstring
                elif isinstance(value, classmethod) or isinstance(value, staticmethod):
                    docstring = getattr(type(self).__dict__[name], '__doc__') or ''
                    class_dict[name] = docstring
                elif issubclass(value, object):
                    class_dict[name] = self._generate_dict(value)
        return class_dict

