            pass  # Auto-possibly derived from proxy's platform
        else:
            pass  # Else, it's 'this' or it's specific to a custom platform
        return what

    splitter = {
        1: re.compile(r'[^\w\s]|_'),
        0: re.compile(r'[^\W\s]|_')
    }.get(platform_local(1), re.compile(r'[^\w\s]|_'))

    def split_line(line):
        """Split a line using a regular expression."""
