def make_path_pattern(pattern):
    path_regex = r'(.*)?{0:s}\*\*(\d{{1,2}})?({0:s})?$'.format(
        re.escape('^' if pattern.endswith('^') else ''),
        re.escape('$' if pattern.startswith('$') else ''),
        re.escape(pattern)
    )

    match = re.search(path_regex, pattern)
    if not match:
