import yaml

def validate_from_content(cls, spec_content=None):
    if spec_content is None:
        raise IRValidatorException("Spec content must be provided")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Invalid YAML content: {e}")

    if all(key in spec for key in cls.REQUIRED_FIELDS):
        return spec
    else:
        raise IRValidatorException(f"Missing mandatory data in spec file: {cls.REQUIRED_FIELDS}")
