def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silenced_args = set()
    silencer = set()
    for opt, val, arg, keyopts in argparser_parse_args(args):
        if opt.startswith('-S') or opt.startswith('--silence'):
            silencer.add(opt)
        elif opt.startswith('-N') or opt.startswith('--no-silence'):
            silenced_args.add(opt)
    return list(silenced_args.union(silencer))
