from typing import Dict, List, Optional

@staticmethod
def merge_extra_vars(vars_dict: Dict[str, Dict[str, str]], extra_vars: Optional[List[Dict[str, str]]] = None) -> Dict[str, Dict[str, str]]:
    if extra_vars is None:
        return vars_dict
    if not vars_dict:
        return vars_dict

    if not extra_vars:
        return vars_dict

    extended_vars = vars_dict.copy()
    for extra in extra_vars:
        for key, value in extra.items():
            if key in extended_vars:
                extended_vars[key] = {**extended_vars[key], key: value}
            else:
                extended_vars[key] = {key: value}

    return extended_vars
